void Store::LogBytes(uint64_t t,uint32_t role,uint32_t slot,const char* raw,size_t copied,int64_t reported,const Digest& source){if(slot>1||!raw)return;std::lock_guard<std::mutex> lock(mutex_);const auto* attempt=Find(t);if(!attempt||attempt->words[107]==2||!Mutation(Now()))return;auto& log=payload_.logs[slot];log={};size_t n=std::min(copied,log.raw.size());Put(log.header.data(),0,t);log.header[2]=role;log.header[3]=uint32_t(n);log.header[4]=uint32_t(std::max<int64_t>(0,reported));log.header[5]=copied>n||reported>int64_t(n+1)?1:0;std::copy(source.begin(),source.end(),log.header.begin()+6);std::memcpy(log.raw.data(),raw,n);auto& c=payload_.control;size_t at=slot?66:60;c[at]=uint32_t(n);c[at+1]=log.header[4];c[at+2]=log.header[5];c[at+3]=role;Put(c.data(),slot?70:64,t);std::copy(source.begin(),source.end(),c.begin()+(slot?80:72));const uint64_t dropped=uint64_t(std::max<size_t>(copied,reported>0?size_t(reported-1):0)-n);if(dropped>UINT64_MAX-Get(c.data(),26))c[34]|=16;else if(dropped)Put(c.data(),26,Get(c.data(),26)+dropped);}
